   615	g_uri_split_internal (const gchar  *uri_string,
   616	                      GUriFlags     flags,
   617	                      gchar       **scheme,
   618	                      gchar       **userinfo,
   619	                      gchar       **user,
   620	                      gchar       **password,
   621	                      gchar       **auth_params,
   622	                      gchar       **host,
   623	                      gint         *port,
   624	                      gchar       **path,
   625	                      gchar       **query,
   626	                      gchar       **fragment,
   627	                      GError      **error)
   628	{
   629	  const gchar *end, *colon, *at, *path_start, *semi, *question;
   630	  const gchar *p, *bracket, *hostend;
   631	  gchar *cleaned_uri_string = NULL;
   632	
   633	  if (scheme)
   634	    *scheme = NULL;
   635	  if (userinfo)
   636	    *userinfo = NULL;
   637	  if (password)
   638	    *password = NULL;
   639	  if (auth_params)
   640	    *auth_params = NULL;
   641	  if (host)
   642	    *host = NULL;
   643	  if (port)
   644	    *port = -1;
   645	  if (path)
   646	    *path = NULL;
   647	  if (query)
   648	    *query = NULL;
   649	  if (fragment)
   650	    *fragment = NULL;
   651	
   652	  if (!(flags & G_URI_FLAGS_PARSE_STRICT) && strpbrk (uri_string, " \t\n\r"))
   653	    {
   654	      cleaned_uri_string = uri_cleanup (uri_string);
   655	      uri_string = cleaned_uri_string;
   656	    }
   657	
   658	  /* Find scheme */
   659	  p = uri_string;
   660	  while (*p && (g_ascii_isalpha (*p) ||
   661	               (p > uri_string && (g_ascii_isdigit (*p) ||
   662	                                   *p == '.' || *p == '+' || *p == '-'))))
   663	    p++;
   664	
   665	  if (p > uri_string && *p == ':')
   666	    {
   667	      if (scheme)
   668	        *scheme = g_ascii_strdown (uri_string, p - uri_string);
   669	      p++;
   670	    }
   671	  else
   672	    {
   673	      if (scheme)
   674	        *scheme = NULL;
   675	      p = uri_string;
   676	    }
   677	
   678	  /* Check for authority */
   679	  if (strncmp (p, "//", 2) == 0)
   680	    {
   681	      p += 2;
   682	
   683	      path_start = p + strcspn (p, "/?#");
   684	      at = memchr (p, '@', path_start - p);
   685	      if (at)
   686	        {
   687	          if (!(flags & G_URI_FLAGS_PARSE_STRICT))
   688	            {
   689	              gchar *next_at;
   690	
   691	              /* Any "@"s in the userinfo must be %-encoded, but
   692	               * people get this wrong sometimes. Since "@"s in the
   693	               * hostname are unlikely (and also wrong anyway), assume
   694	               * that if there are extra "@"s, they belong in the
   695	               * userinfo.
   696	               */
   697	              do
   698	                {
   699	                  next_at = memchr (at + 1, '@', path_start - (at + 1));
   700	                  if (next_at)
   701	                    at = next_at;
   702	                }
   703	              while (next_at);
   704	            }
   705	
   706	          if (user || password || auth_params ||
   707	              (flags & (G_URI_FLAGS_HAS_PASSWORD|G_URI_FLAGS_HAS_AUTH_PARAMS)))
   708	            {
   709	              if (!parse_userinfo (p, at - p, flags,
   710	                                   user, password, auth_params,
   711	                                   error))
   712	                goto fail;
   713	            }
   714	
   715	          if (!uri_normalize (userinfo, p, at - p, flags,
   716	                              G_URI_ERROR_BAD_USER, error))
   717	            goto fail;
   718	
   719	          p = at + 1;
   720	        }
   721	
   722	      if (!(flags & G_URI_FLAGS_PARSE_STRICT))
   723	        {
   724	          semi = strchr (p, ';');
   725	          if (semi && semi < path_start)
   726	            {
   727	              /* Technically, semicolons are allowed in the "host"
   728	               * production, but no one ever does this, and some
   729	               * schemes mistakenly use semicolon as a delimiter
   730	               * marking the start of the path. We have to check this
   731	               * after checking for userinfo though, because a
   732	               * semicolon before the "@" must be part of the
   733	               * userinfo.
   734	               */
   735	              path_start = semi;
   736	            }
   737	        }
   738	
   739	      /* Find host and port. The host may be a bracket-delimited IPv6
   740	       * address, in which case the colon delimiting the port must come
   741	       * (immediately) after the close bracket.
   742	       */
   743	      if (*p == '[')
   744	        {
   745	          bracket = memchr (p, ']', path_start - p);
   746	          if (bracket && *(bracket + 1) == ':')
   747	            colon = bracket + 1;
   748	          else
   749	            colon = NULL;
   750	        }
   751	      else
   752	        colon = memchr (p, ':', path_start - p);
   753	
   754	      hostend = colon ? colon : path_start;
   755	      if (!parse_host (p, hostend - p, flags, host, error))
   756	        goto fail;
   757	
   758	      if (colon && colon != path_start - 1)
   759	        {
   760	          p = colon + 1;
   761	          if (!parse_port (p, path_start - p, port, error))
   762	            goto fail;
   763	        }
   764	
   765	      p = path_start;
   766	    }
   767	
   768	  /* Find fragment. */
   769	  end = p + strcspn (p, "#");
   770	  if (*end == '#')
   771	    {
   772	      if (!uri_decode (fragment, end + 1, strlen (end + 1), flags,
   773	                       G_URI_ERROR_BAD_FRAGMENT, error))
   774	        goto fail;
   775	    }
   776	
   777	  /* Find query */
   778	  question = memchr (p, '?', end - p);
   779	  if (question)
   780	    {
   781	      if (!uri_normalize (query, question + 1, end - (question + 1), flags,
   782	                          G_URI_ERROR_BAD_QUERY, error))
   783	        goto fail;
   784	      end = question;
   785	    }
   786	
   787	  if (!uri_normalize (path, p, end - p, flags,
   788	                      G_URI_ERROR_BAD_PATH, error))
   789	    goto fail;
   790	
   791	  g_free (cleaned_uri_string);
   792	  return TRUE;
   793	
   794	 fail:
   795	  if (scheme)
   796	    g_clear_pointer (scheme, g_free);
   797	  if (userinfo)
   798	    g_clear_pointer (userinfo, g_free);
   799	  if (host)
   800	    g_clear_pointer (host, g_free);
